{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Membership Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfdfa;--ink:#10323b;--muted:#6b7b80;--accent:#7aa89a;--card:#ffffff}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;color:var(--ink);margin:0;background:linear-gradient(180deg,#fbfdfa 0%,#f4fbf9 100%);}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 32px;border-bottom:1px solid rgba(16,50,59,.06);background:transparent}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .brand{font-weight:700;letter-spacing:.3px}
    .wrap{max-width:1100px;margin:28px auto;padding:0 24px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start;margin-bottom:28px}
    .hero h1{margin:0 0 12px;font-size:28px}
    .lead{color:var(--muted);margin:0 0 18px}
    .cta{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:8px;text-decoration:none}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 8px 30px rgba(16,50,59,.06)}
    .plans{display:flex;gap:14px;margin-top:18px}
    .plan{flex:1;padding:16px;border-radius:10px;border:1px solid rgba(16,50,59,0.06)}
    .plan h3{margin:0 0 8px}
    .price{font-size:20px;font-weight:700;color:var(--ink)}
    .small{color:var(--muted);font-size:14px}
    .muted{color:var(--muted)}
    footer{padding:24px;text-align:center;color:var(--muted)}

    /* Background pattern SVG sits in DOM */
    .bg-pattern{position:fixed;right:-120px;top:-60px;opacity:.12;width:520px;height:520px;pointer-events:none}

    /* Aroma wheel */
    .wheel-wrap{display:flex;gap:18px;align-items:center}
    .wheel{width:220px;height:220px;border-radius:50%;position:relative;display:grid;place-items:center;background:conic-gradient(#f7fff9 0 120deg,#f2faf8 120deg 240deg,#eef7f6 240deg 360deg);box-shadow:inset 0 6px 20px rgba(10,30,30,.03)}
    .ring{position:absolute;width:88%;height:88%;border-radius:50%;display:grid;place-items:center}
    .note{position:absolute;transform-origin:center;cursor:pointer;font-size:13px;color:var(--ink);padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.7);backdrop-filter:blur(4px);border:1px solid rgba(16,50,59,.04)}
    .note.top{top:8%;left:50%;transform:translateX(-50%)}
    .note.middle{top:50%;right:6%;transform:translateY(-50%)}
    .note.base{bottom:10%;left:50%;transform:translateX(-50%)}
    .note:hover{background:var(--accent);color:white}
    .note-desc{max-width:320px}

    /* Mood selector */
    .selector{display:flex;gap:8px;flex-wrap:wrap}
    .mood{padding:8px 12px;border-radius:999px;border:1px solid rgba(16,50,59,.06);background:white;cursor:pointer}
    .mood.active{background:var(--accent);color:white;border-color:transparent}

    @media (max-width:900px){.hero{grid-template-columns:1fr;}.wheel-wrap{flex-direction:column;align-items:start}.hero h1{font-size:22px}}
  </style>
</head>
<body>
  <svg class="bg-pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#c7efe3"/><stop offset="1" stop-color="#eaf9f3"/></linearGradient>
    </defs>
    <rect x="0" y="0" width="200" height="200" fill="url(#g1)" rx="20"/>
    <g fill="#8fc8b5" opacity=".6">
      <circle cx="40" cy="40" r="6"/>
      <circle cx="80" cy="70" r="4"/>
      <circle cx="150" cy="30" r="10"/>
    </g>
    <path d="M10 180 Q 60 140 120 170" stroke="#a8d6c6" stroke-width="3" fill="none" opacity=".5"/>
  </svg>

  <header>
    <div class="brand">Studio Scent — Atelier</div>
    <nav aria-label="Main">
      <a href="index.html">Sanctum</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Distillations</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Memberships</a>
      <a href="about.html">The Atelier</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div>
        <h1>Memberships framed around rhythm and care</h1>
        <p class="lead">A structured scent subscription that may support calmer routines and steady habit-building. Choose the cadence that fits your life; benefits scale with membership tier.</p>
        <div class="card" style="margin-top:12px">
          <strong style="display:block">Try the Mood-to-Method tool</strong>
          <p class="muted">Select how you feel right now to see a recommended membership approach.</p>
          <div style="margin-top:10px" class="selector" id="mood-buttons">
            <button class="mood" data-mood="stressed">Stressed</button>
            <button class="mood" data-mood="sleepy">Sleepy</button>
            <button class="mood" data-mood="scattered">Scattered</button>
            <button class="mood" data-mood="steadied">Grounded</button>
          </div>
          <div style="display:flex;gap:10px;align-items:center;margin-top:12px">
            <div id="method-card" style="flex:1">
              <div style="font-weight:700" id="method-title">Balanced Rituals</div>
              <div class="small muted" id="method-desc">A hybrid flow combining short weekly practices with monthly guidance.</div>
            </div>
            <a id="primary-cta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="plans" style="margin-top:18px">
          <div class="plan card">
            <h3>Seed Circle</h3>
            <div class="price">$18 / month</div>
            <div class="small muted">Monthly sample blend + community notes. For light, steady ritual.</div>
            <ul class="small muted" style="margin-top:8px;padding-left:16px">
              <li>Quarterly education briefs</li>
              <li>2 sample blends / year</li>
            </ul>
          </div>
          <div class="plan card">
            <h3>Root Collective</h3>
            <div class="price">$48 / month</div>
            <div class="small muted">Core membership for paced practices and replenishment.</div>
            <ul class="small muted" style="margin-top:8px;padding-left:16px">
              <li>Monthly blend delivery</li>
              <li>Member-only micro-sessions</li>
            </ul>
          </div>
          <div class="plan card">
            <h3>Canopy Atelier</h3>
            <div class="price">$95 / month</div>
            <div class="small muted">Dedicated guidance, custom blends, and priority booking.</div>
            <ul class="small muted" style="margin-top:8px;padding-left:16px">
              <li>Custom blend quarterly</li>
              <li>Monthly 30-min consult</li>
            </ul>
          </div>
        </div>
      </div>

      <aside>
        <div class="card">
          <h4 style="margin-top:0">Aroma Wheel</h4>
          <div class="wheel-wrap">
            <div class="wheel" id="wheel">
              <div class="ring">Notes</div>
              <div class="note top" data-type="top" data-note="bergamot">Bergamot</div>
              <div class="note middle" data-type="middle" data-note="lavender">Lavender</div>
              <div class="note base" data-type="base" data-note="vetiver">Vetiver</div>
            </div>
            <div class="note-desc card" id="note-desc">
              <strong id="note-title">Hover a note</strong>
              <p id="note-text" class="small muted">Hover or focus a note to read a short, safety-forward description of how it may be used.</p>
            </div>
          </div>
          <div style="font-size:12px;color:var(--muted);margin-top:12px">Non-medical guidance: suggestions may support mood or comfort. See FAQ for dilution and safety notes.</div>
        </div>
      </aside>
    </section>

    <section class="card" style="margin-bottom:22px">
      <h3 style="margin-top:0">Why membership?</h3>
      <p class="muted">Regular, small scent practices can create a steady scaffold for routines. Memberships are structured to simplify decisions: choose the pace that fits your life, receive blends and guidance, and access member sessions as needed.</p>
    </section>

    <section class="card">
      <h4 style="margin-top:0">Questions</h4>
      <p class="small muted"><strong>Patch testing & dilution:</strong> Always dilute essential oils according to guidance and perform a small patch test before new blends. For base dilution ratios, consult session notes or ask during your consult.</p>
      <p class="small muted"><strong>Pregnancy & pets:</strong> Some oils are not suggested during pregnancy or around certain animals. Inform your practitioner; we recommend consulting your healthcare provider for specific concerns.</p>
    </section>

  </main>

  <footer>
    <div class="small muted">Contact: {{EMAIL}} • {{PHONE}} • {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    // Mood-to-Method logic
    const moods = {
      stressed: {title:"Short Resets",desc:"Quick inhalation practices + a calming blend delivered monthly. Ideal for frequent on-the-go reset." ,cta:"Begin a Reset"},
      sleepy: {title:"Nightly Ease",desc:"Evening ritual blends and a gentle sleep-focused micro-habit plan.",cta:"Try Sleep Rituals"},
      scattered: {title:"Focus Sequence",desc:"A focused packet of mid-day boosts and scent cues for clearer attention.",cta:"Start Focus Plan"},
      steadied: {title:"Maintenance Cycle",desc:"A monthly replenishment plus occasional consults to keep your routine steady.",cta:"Join Maintenance"}
    };
    const moodButtons = document.getElementById('mood-buttons');
    const methodTitle = document.getElementById('method-title');
    const methodDesc = document.getElementById('method-desc');
    const primaryCta = document.getElementById('primary-cta');

    moodButtons.addEventListener('click', (e)=>{
      const btn = e.target.closest('.mood');
      if(!btn) return;
      [...moodButtons.querySelectorAll('.mood')].forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const key = btn.dataset.mood;
      const m = moods[key];
      methodTitle.textContent = m.title;
      methodDesc.textContent = m.desc;
      primaryCta.textContent = m.cta;
      primaryCta.href = '{{PRIMARY_CTA_URL}}?mood='+encodeURIComponent(key);
    });

    // Aroma wheel interactivity
    const notes = {
      bergamot:{title:'Bergamot — top note',text:'A bright citrus top note that may support uplift and clarity when used modestly.'},
      lavender:{title:'Lavender — middle note',text:'A calm, floral middle note often used for relaxation. May support reduced tension with careful use.'},
      vetiver:{title:'Vetiver — base note',text:'A grounding base note with earthy depth. Used in small dilutions, it may support steadiness.'}
    };
    const noteDesc = document.getElementById('note-desc');
    const noteTitle = document.getElementById('note-title');
    const noteText = document.getElementById('note-text');
    document.querySelectorAll('.note').forEach(n=>{
      n.addEventListener('mouseenter',()=>{
        const key = n.dataset.note;
        noteTitle.textContent = notes[key].title;
        noteText.textContent = notes[key].text;
      });
      n.addEventListener('focus',()=>{
        const key = n.dataset.note;
        noteTitle.textContent = notes[key].title;
        noteText.textContent = notes[key].text;
      });
      n.addEventListener('mouseleave',()=>{
        noteTitle.textContent = 'Hover a note';
        noteText.textContent = 'Hover or focus a note to read a short, safety-forward description of how it may be used.';
      });
    });
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — The Atelier</title>
  <style>
    :root{--bg:#fffefb;--ink:#0f3a3a;--muted:#617274;--accent:#8fc0a9}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;color:var(--ink);margin:0;background:var(--bg)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;border-bottom:1px solid rgba(15,58,58,.06)}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:980px;margin:28px auto;padding:0 20px}
    .intro{display:flex;gap:18px}
    .intro .who{flex:1}
    .intro .meta{width:320px}
    h1{margin:0 0 8px;font-size:26px}
    .muted{color:var(--muted)}
    .card{background:white;padding:16px;border-radius:12px;box-shadow:0 10px 30px rgba(12,36,36,.04)}
    .grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}
    .faq dt{font-weight:700;margin-top:12px}
    .faq dd{margin:6px 0 0;color:var(--muted)}
    .wheel-small{display:flex;gap:12px;align-items:center;margin-top:12px}
    .wheel-mini{width:120px;height:120px;border-radius:50%;background:conic-gradient(#f4f9f7 0 120deg,#eef8f6 120deg 240deg,#e9f4ef 240deg 360deg);display:grid;place-items:center;position:relative}
    .mini-note{position:absolute;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.8);font-size:13px}
    .mini-note.top{top:8%;left:50%;transform:translateX(-50%)}
    .mini-note.middle{right:6%;top:50%;transform:translateY(-50%)}
    .mini-note.base{bottom:8%;left:50%;transform:translateX(-50%)}
    .mood-row{margin-top:12px;display:flex;gap:8px}
    .mood-input{padding:8px 10px;border-radius:8px;border:1px solid rgba(15,58,58,.06);background:white;cursor:pointer}
    @media(max-width:740px){.intro{flex-direction:column}.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">Atelier: Scent Lab</div>
    <nav>
      <a href="index.html">Sanctum</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Distillations</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Memberships</a>
      <a href="about.html">The Atelier</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="intro">
      <div class="who card">
        <h1>Our approach</h1>
        <p class="muted">We combine scent science literacy with patient-centered practice. Our sessions and blends are curated to be safety-forward and pragmatic; language focuses on how scent practices may support daily ease rather than on clinical outcomes.</p>

        <div class="grid">
          <div class="card">
            <h4 style="margin:0">What we do</h4>
            <p class="muted small">Design gentle, evidence-aware scent practices and membership rhythms that help simplify daily choices. We orient toward sustainable usage and clear, incremental routines.</p>
          </div>
          <div class="card">
            <h4 style="margin:0">Who we serve</h4>
            <p class="muted small">People seeking guided scent practices that fold into everyday life—those new to aromatherapy and experienced clients seeking structure.</p>
          </div>
        </div>
      </div>

      <aside class="meta">
        <div class="card">
          <h4 style="margin-top:0">Meet the team</h4>
          <p class="muted">A small collective of trained practitioners and botanical-curious designers. Sessions emphasize safety, clear instructions, and habitable rituals.</p>

          <div class="wheel-small" aria-hidden>
            <div class="wheel-mini" id="about-wheel">
              <div class="mini-note top" data-note="bergamot">Bergamot</div>
              <div class="mini-note middle" data-note="clary">Clary</div>
              <div class="mini-note base" data-note="sandalwood">Sandalwood</div>
            </div>
            <div style="flex:1">
              <div style="font-weight:700">Aroma snapshot</div>
              <div class="muted small" id="about-note-desc">Hover a segment for a short line about common uses.</div>
            </div>
          </div>
        </div>
      </aside>
    </section>

    <section class="card" style="margin-top:16px">
      <h3 style="margin-top:0">FAQ & Safety</h3>
      <dl class="faq">
        <dt>Patch testing and dilution</dt>
        <dd>We recommend a small patch test for new blends and follow conservative dilution guidelines. If you receive blends through membership, dilution notes are included with each shipment.</dd>

        <dt>Pregnancy</dt>
        <dd>Certain oils are typically recommended to be avoided during pregnancy. Please inform your practitioner; all recommendations are framed to be safety-first and non-diagnostic.</dd>

        <dt>Pets</dt>
        <dd>Some essential oils can be impactful for animals. Keep blends away from close, unsupervised exposure to pets and check with a veterinarian for species-specific concerns.</dd>

        <dt>Medical guidance</dt>
        <dd>Information here is not a substitute for professional medical advice. Scent practices may support comfort or routines but are not medical treatments.</dd>
      </dl>
    </section>

    <section class="card" style="margin-top:16px">
      <h4 style="margin-top:0">Community agreements</h4>
      <p class="muted">We ask members to use blends responsibly, store oils safely, and to reach out with questions. Respectful practice keeps the Atelier welcoming.</p>
    </section>

    <section class="card" style="margin-top:16px">
      <h4 style="margin-top:0">Try the Mood-to-Method here</h4>
      <div class="mood-row" id="about-moods">
        <button class="mood-input" data-mood="anxious">Anxious</button>
        <button class="mood-input" data-mood="tired">Tired</button>
        <button class="mood-input" data-mood="busy">Busy</button>
        <button class="mood-input" data-mood="steady">Steady</button>
      </div>
      <div style="margin-top:12px" id="about-method">Select a mood to reveal a suggested practice and next step.</div>
    </section>

  </main>

  <footer style="padding:18px 20px;text-align:center;color:var(--muted)">Contact: {{EMAIL}} • {{PHONE}}</footer>

  <script>
    // Simple about-page aroma small interactions
    const aboutNotes = {
      bergamot:'Citrus uplift often used sparingly to support alertness or gentle mood shifts.',
      clary:'A floral-woody middle note sometimes used in evening blends for a soft settling effect.',
      sandalwood:'Warm, slow base note often chosen for grounding in tiny dilutions.'
    };
    document.querySelectorAll('#about-wheel .mini-note').forEach(n=>{
      n.addEventListener('mouseenter',()=>{
        const key = n.dataset.note;
        document.getElementById('about-note-desc').textContent = aboutNotes[key];
      });
      n.addEventListener('mouseleave',()=>{
        document.getElementById('about-note-desc').textContent = 'Hover a segment for a short line about common uses.';
      });
    });

    // Mood-to-Method (about)
    const aboutMap = {
      anxious:{text:'Breathing blends + short inhale breaks. A weekly mini-plan may help build calm cues.', action:'Explore Reset Kits'},
      tired:{text:'Evening routine with low-odour supportive bases; favor calming sequences.', action:'View Evening Packs'},
      busy:{text:'Portable inhalers for quick focus; micro-habits to anchor transitions.', action:'See Pocket Sets'},
      steady:{text:'Maintenance rhythm: monthly replenishment and optional check-ins.', action:'Join Atelier'}
    };
    document.getElementById('about-moods').addEventListener('click', (e)=>{
      const btn = e.target.closest('.mood-input');
      if(!btn) return;
      const key = btn.dataset.mood;
      const info = aboutMap[key];
      document.getElementById('about-method').textContent = info.text + ' — ' + info.action + '.';
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Session</title>
  <style>
    :root{--bg:#f8fffb;--ink:#073236;--muted:#556a6a;--accent:#6db29f}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:var(--ink);margin:0}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;border-bottom:1px solid rgba(7,50,54,.06)}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:26px auto;padding:0 18px}
    h1{font-size:24px;margin:0}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .card{background:white;padding:16px;border-radius:12px;box-shadow:0 8px 24px rgba(7,50,54,.04)}
    label{display:block;margin-top:10px;font-weight:700}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(7,50,54,.08);margin-top:6px}
    .btn{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none;border:none;cursor:pointer}
    .micro{font-size:13px;color:var(--muted)}
    .session-type{display:flex;gap:8px;margin-top:10px}
    .session-option{padding:8px 10px;border-radius:8px;border:1px solid rgba(7,50,54,.06);cursor:pointer}
    .session-option.active{background:var(--accent);color:white}
    .wheel-book{display:flex;gap:12px;align-items:center}
    .wheel-book .note{padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.85);border:1px solid rgba(7,50,54,.04)}
    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">Book — Ateliers</div>
    <nav>
      <a href="index.html">Sanctum</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Distillations</a>
      <a href="shop.html">Boutique</a>
      <a href="pricing.html">Memberships</a>
      <a href="about.html">The Atelier</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Schedule a guided session</h1>
    <p class="micro">Choose a session tempo and tell us how you feel. Recommendations are safety-focused and framed to support daily practices.</p>

    <div class="grid">
      <div>
        <div class="card">
          <label for="name">Name</label>
          <input id="name" placeholder="Your name" />

          <label for="email">Email</label>
          <input id="email" placeholder="you@example.com" />

          <label for="phone">Phone (optional)</label>
          <input id="phone" placeholder="(optional)" />

          <label>Session style</label>
          <div class="session-type" id="session-types">
            <button class="session-option" data-type="explore">Exploratory (30m)</button>
            <button class="session-option" data-type="practical">Practical (45m)</button>
            <button class="session-option" data-type="deep">Deep Blend (60m)</button>
          </div>

          <label>How are you right now?</label>
          <div style="display:flex;gap:8px;margin-top:8px" id="book-moods">
            <button class="session-option" data-mood="anxious">Anxious</button>
            <button class="session-option" data-mood="foggy">Foggy</button>
            <button class="session-option" data-mood="fatigued">Fatigued</button>
            <button class="session-option" data-mood="calm">Calm</button>
          </div>

          <label for="notes">Notes (allergies, pregnancy, pets)</label>
          <textarea id="notes" placeholder="Tell us about sensitivities or concerns" rows="4"></textarea>

          <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
            <button id="confirm-book" class="btn">Book a Session</button>
            <div class="micro muted">Or <a href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin-top:0">Safety notes</h4>
          <p class="micro">We will ask about pregnancy and pets. Some oils are not suggested in pregnancy or around certain animals. Please note any medications or sensitivities in the notes; recommendations are not medical advice.</p>
        </div>
      </div>

      <aside>
        <div class="card">
          <h4 style="margin-top:0">Recommended method</h4>
          <div id="rec-method" style="font-weight:700">Balanced Inhale + Micro Ritual</div>
          <div class="micro muted" id="rec-desc">Select a mood and a session style to see a tailored, safety-oriented suggestion.</div>

          <div style="margin-top:12px">
            <h5 style="margin:0">Aroma Wheel</h5>
            <div class="wheel-book card" style="margin-top:8px;padding:12px">
              <div class="note" data-note="lime">Lime — top</div>
              <div class="note" data-note="geranium">Geranium — middle</div>
              <div class="note" data-note="patchouli">Patchouli — base</div>
            </div>
            <div class="micro muted" id="wheel-info" style="margin-top:8px">Hover a note for a short description.</div>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin-top:0">Quick policy</h4>
          <p class="micro">Cancellations: please notify 24 hours prior. For pregnancy, pet concerns, or medical conditions, we will adjust blends and avoid certain oils.</p>
        </div>
      </aside>
    </div>
  </main>

  <footer style="padding:18px;text-align:center;color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</footer>

  <script>
    // Booking interactivity: session + mood combine into recommended method
    const sessionTypes = {
      explore:{label:'Exploratory (30m)',desc:'Short consultation to learn your preferences and try a simple inhalation blend.'},
      practical:{label:'Practical (45m)',desc:'Hands-on plan with portable tools and a small routine to practice.'},
      deep:{label:'Deep Blend (60m)',desc:'Custom blend formulation with a deeper review of sensitivities and patterns.'}
    };
    const moodMap = {
      anxious:{method:'Micro Inhaler + Breath Pause',note:'Short, repeatable inhalation cues with calming middle notes.'},
      foggy:{method:'Citrus-Anchor Sequence',note:'Bright top notes paired with grounding base to support clarity.'},
      fatigued:{method:'Gentle Evening Flow',note:'Low-odour bases and relaxing sequences for winding down.'},
      calm:{method:'Maintenance Blend',note:'Balanced blends for steady routine support.'}
    };

    let chosenSession = 'practical';
    let chosenMood = 'calm';

    document.getElementById('session-types').addEventListener('click',(e)=>{
      const btn = e.target.closest('.session-option');
      if(!btn) return;
      [...document.querySelectorAll('#session-types .session-option')].forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      chosenSession = btn.dataset.type;
      updateRecommendation();
    });

    document.getElementById('book-moods').addEventListener('click',(e)=>{
      const btn = e.target.closest('.session-option');
      if(!btn) return;
      [...document.querySelectorAll('#book-moods .session-option')].forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      chosenMood = btn.dataset.mood;
      updateRecommendation();
    });

    function updateRecommendation(){
      const session = sessionTypes[chosenSession];
      const mood = moodMap[chosenMood];
      document.getElementById('rec-method').textContent = mood.method + ' — ' + session.label;
      document.getElementById('rec-desc').textContent = mood.note + ' ' + session.desc;
      document.getElementById('confirm-book').textContent = 'Book: '+(session.label.split(' ')[0])+' — '+mood.method;
    }
    updateRecommendation();

    // Aroma wheel hover
    const wheelNotes = {
      lime:'Lime (top): bright citrus often used lightly to support alertness.',
      geranium:'Geranium (middle): floral-herbal used in small dilutions for balance.',
      patchouli:'Patchouli (base): earthy base note used sparingly; supports depth in blends.'
    };
    document.querySelectorAll('.wheel-book .note').forEach(n=>{
      n.addEventListener('mouseenter',()=>{
        document.getElementById('wheel-info').textContent = wheelNotes[n.dataset.note];
      });
      n.addEventListener('mouseleave',()=>{
        document.getElementById('wheel-info').textContent = 'Hover a note for a short description.';
      });
    });

    // Confirm booking (no real backend) — basic flow
    document.getElementById('confirm-book').addEventListener('click',()=>{
      const name = document.getElementById('name').value || 'Guest';
      alert('Thanks '+name+" — we'll follow up at " + (document.getElementById('email').value || 'your email') + '.');
    });
  </script>
</body>
</html>"} 
